import { lerp, clamp, ease } from "./helpers";

export const RX = 32;
export const RY = 24;

export default function HeroCard({ card, progress, vw }) {
  /*
   * ── Orbit radii ──
   * Desktop (lg ≥ 1024): UNCHANGED — 40vw / 30vh
   * Tablet  (md 600–1023): slightly tighter
   * Mobile  (sm 400–599):  compact orbit that fits the screen
   * XSmall  (xs < 400):    very tight — cards must not bleed off screen
   *
   * Key insight: on small screens vw-based rx values still work, but
   * the *actual pixel* radius is tiny, so we boost the vw percentage
   * to keep cards visually separated.
   */
  const rx = vw >= 1024 ? 40            // desktop — unchanged
           : vw >= 600  ? 32            // tablet
           : vw >= 400  ? 36            // small phone — slightly wider %
           :              34;           // xs — tight but visible

  const ry = vw >= 1024 ? 30            // desktop — unchanged
           : vw >= 600  ? 22            // tablet
           : vw >= 400  ? 24            // small phone
           :              22;           // xs

  /*
   * ── Card dimensions ──
   * Desktop unchanged. Scaled down proportionally for smaller screens.
   */
  const cardWidth  = vw >= 1024 ? 190
                   : vw >= 600  ? 142
                   : vw >= 400  ? 100
                   :              86;

  const cardHeight = vw >= 1024 ? 234
                   : vw >= 600  ? 175
                   : vw >= 400  ? 123
                   :              106;

  const borderRad  = vw >= 1024 ? 20
                   : vw >= 600  ? 13
                   :              9;

  /*
   * ── Explode distance ──
   * Desktop unchanged (172). Reduced on smaller screens so cards
   * don't fly off the viewport edge.
   */
  const explodeDist = vw >= 1024 ? 172
                    : vw >= 600  ? 126
                    : vw >= 400  ? 96
                    :              80;

  const rad = (card.angle * Math.PI) / 180;
  const ox  = Math.cos(rad) * rx;
  const oy  = -Math.sin(rad) * ry;
  const mag = Math.sqrt(ox * ox + oy * oy) || 1;
  const EX  = (ox / mag) * explodeDist;
  const EY  = (oy / mag) * explodeDist;

  const t       = ease(clamp((progress - 0.35) / 0.55, 0, 1));
  const tx      = lerp(ox, EX, t);
  const ty      = lerp(oy, EY, t);
  const opacity = lerp(1, 0, clamp((progress - 0.65) / 0.3, 0, 1));

  /*
   * Shadow direction derived from card angle so each card feels
   * lit from the center — unchanged logic, only shadow magnitude
   * reduced slightly on mobile for less visual noise.
   */
  const shadowMag = vw >= 600 ? 6 : 4;
  const shadowX   = +(Math.cos(rad) * shadowMag).toFixed(1);
  const shadowY   = -(Math.sin(rad) * shadowMag).toFixed(1);

  /*
   * On mobile, reduce the perspective tilt so cards don't look
   * oddly distorted at small sizes.
   */
  const tiltScale = vw >= 1024 ? 1 : vw >= 600 ? 0.7 : 0.4;
  const rotateXDeg = (Math.sin(rad) * 6 * tiltScale).toFixed(1);
  const rotateYDeg = (-(Math.cos(rad) * 4 * tiltScale)).toFixed(1);

  return (
    <div
      style={{
        position: "absolute",
        left: `calc(50% + ${tx}vw)`,
        top: `calc(50% + ${ty}vh)`,
        transform: `
          translate(-50%, -50%)
          perspective(800px)
          rotate(${card.rotate}deg)
          rotateX(${rotateXDeg}deg)
          rotateY(${rotateYDeg}deg)
        `,
        opacity,
        zIndex: card.z,
        willChange: "transform, opacity",
        pointerEvents: "none",
        filter: `drop-shadow(${shadowX}px ${shadowY}px 18px rgba(0,0,0,0.60))
                 drop-shadow(0px 4px 8px rgba(0,0,0,0.30))`,
      }}
    >
      <div
        style={{
          width: cardWidth,
          height: cardHeight,
          borderRadius: borderRad,
          overflow: "hidden",
          display: "flex",
          flexDirection: "column",
          position: "relative",
          boxShadow: "inset 0 0 0 1px rgba(255,255,255,0.10)",
        }}
      >
        <div style={{ flex: 1, position: "relative", overflow: "hidden" }}>
          <img
            src={`/assets/img${card.id}.png`}
            alt=""
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              display: "block",
            }}
          />
        </div>
      </div>
    </div>
  );
}
